import{_ as p,r as n,o as c,c as r,e as s,a as t,s as e}from"./chunks/framework.CXcwiNg-.js";const y=JSON.parse('{"title":"表单字段 - October CMS - 3.x","titleTemplate":false,"description":"了解不同的表单字段类型。","frontmatter":{"subtitle":"了解不同的表单字段类型。"},"headers":[{"level":2,"title":"可用字段","slug":"可用字段","link":"#可用字段","children":[]},{"level":2,"title":"字段属性","slug":"字段属性","link":"#字段属性","children":[{"level":3,"title":"选项卡属性","slug":"选项卡属性","link":"#选项卡属性","children":[]},{"level":3,"title":"自定义字段类型","slug":"自定义字段类型","link":"#自定义字段类型","children":[]},{"level":3,"title":"嵌套字段选择","slug":"嵌套字段选择","link":"#嵌套字段选择","children":[]},{"level":3,"title":"字段门面","slug":"字段门面","link":"#字段门面","children":[]}]},{"level":2,"title":"字段条件","slug":"字段条件","link":"#字段条件","children":[{"level":3,"title":"触发器事件","slug":"触发器事件","link":"#触发器事件","children":[{"level":4,"title":"多个操作","slug":"多个操作","link":"#多个操作","children":[]},{"level":4,"title":"多值条件","slug":"多值条件","link":"#多值条件","children":[]},{"level":4,"title":"通配符值条件","slug":"通配符值条件","link":"#通配符值条件","children":[]},{"level":4,"title":"多字段值","slug":"多字段值","link":"#多字段值","children":[]},{"level":4,"title":"引用父级字段","slug":"引用父级字段","link":"#引用父级字段","children":[]}]},{"level":3,"title":"输入预设转换器","slug":"输入预设转换器","link":"#输入预设转换器","children":[]}]}],"relativePath":"3.x/zh-cn/element/form-fields.md","filePath":"3.x/zh-cn/element/form-fields.md"}'),d={name:"3.x/zh-cn/element/form-fields.md"};function i(u,a,k,g,h,m){const o=n("pre-heading"),l=n("post-heading");return c(),r("div",null,[s(o),a[0]||(a[0]=t("h1",null,"表单字段",-1)),s(l),a[1]||(a[1]=e(`<p>表单字段、表单 UI 和表单小部件是表单使用的字段定义，例如文本输入框。它们通常在以下区域中使用：</p><ul><li><a href="./../cms/themes/settings.html">CMS 主题设置</a></li><li><a href="./../cms/tailor/content-fields.html">Tailor 内容字段</a></li><li><a href="./../extend/forms/form-controller.html">后端表单控制器</a></li><li><a href="./../extend/forms/relation-controller.html">后端关联控制器</a></li></ul><p>所有表单字段都通过各自的 <strong>type</strong> 属性来标识。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">fields</span><span class="token punctuation">:</span>
    <span class="token key atrule">myfield</span><span class="token punctuation">:</span>
        <span class="token key atrule">type</span><span class="token punctuation">:</span> textarea
        <span class="token comment"># ...</span>
</code></pre></div><p>表单字段包含通用和简单的字段。表单 UI 是可以包含在表单中以帮助布局设计的用户界面元素。表单小部件通常引入更复杂的功能，插件通常会提供自己的自定义表单小部件。Tailor 字段是仅在 Tailor 蓝图内可用的字段。</p><h2 id="可用字段"><a href="#可用字段" class="header-anchor">#</a> 可用字段</h2><p>以下表单字段可用：</p>`,7)),a[2]||(a[2]=t("div",{class:"content-list-p",markdown:"1"},[t("p",null,[t("a",{href:"./content/field-mixin.html"},"Mixin"),t("a",{href:"./content/field-entries.html"},"Entries"),t("a",{href:"./form/field-text.html"},"Text"),t("a",{href:"./form/field-number.html"},"Number"),t("a",{href:"./form/field-password.html"},"Password"),t("a",{href:"./form/field-email.html"},"Email"),t("a",{href:"./form/field-textarea.html"},"Textarea"),t("a",{href:"./form/field-dropdown.html"},"Dropdown"),t("a",{href:"./form/field-radio.html"},"Radio List"),t("a",{href:"./form/field-balloon.html"},"Balloon Selector"),t("a",{href:"./form/field-checkbox.html"},"Checkbox"),t("a",{href:"./form/field-checkboxlist.html"},"Checkbox List"),t("a",{href:"./form/field-switch.html"},"Switch"),t("a",{href:"./form/widget-codeeditor.html"},"Code Editor"),t("a",{href:"./form/widget-colorpicker.html"},"Color Picker"),t("a",{href:"./form/widget-datatable.html"},"Data Table"),t("a",{href:"./form/widget-datepicker.html"},"Date Picker"),t("a",{href:"./form/widget-fileupload.html"},"File Upload"),t("a",{href:"./form/widget-markdown.html"},"Markdown Editor"),t("a",{href:"./form/widget-mediafinder.html"},"Media Finder"),t("a",{href:"./form/widget-nestedform.html"},"Nested Form"),t("a",{href:"./form/widget-recordfinder.html"},"Record Finder"),t("a",{href:"./form/widget-relation.html"},"Relation"),t("a",{href:"./form/widget-repeater.html"},"Repeater"),t("a",{href:"./form/widget-richeditor.html"},"Rich Editor"),t("a",{href:"./form/widget-pagefinder.html"},"Page Finder"),t("a",{href:"./form/widget-sensitive.html"},"Sensitive"),t("a",{href:"./form/widget-taglist.html"},"Tag List"),t("a",{href:"./form/widget-currency.html"},"Currency"),t("a",{href:"./form/widget-boxes.html"},"Boxes"),t("a",{href:"./form/ui-section.html"},"Section"),t("a",{href:"./form/ui-hint.html"},"Hint"),t("a",{href:"./form/ui-ruler.html"},"Ruler"),t("a",{href:"./form/ui-partial.html"},"Partial")])],-1)),a[3]||(a[3]=e(`<h2 id="字段属性"><a href="#字段属性" class="header-anchor">#</a> 字段属性</h2><p>对于每个字段，您可以指定以下通用属性（如适用）。</p><div class="table"><table tabindex="0"><thead><tr><th>属性</th><th>描述</th></tr></thead><tbody><tr><td><strong>label</strong></td><td>向用户显示表单字段时使用的名称。</td></tr><tr><td><strong>type</strong></td><td>定义此字段的渲染方式。默认值：<code>text</code>。</td></tr><tr><td><strong>span</strong></td><td>将表单字段对齐到一侧。选项：<code>auto</code>、<code>left</code>、<code>right</code>、<code>row</code>、<code>full</code>。默认值：<code>full</code>。</td></tr><tr><td><strong>spanClass</strong></td><td>与 span <code>row</code> 属性一起使用，将表单显示为 Bootstrap 网格，例如 <code>spanClass: col-4</code>。</td></tr><tr><td><strong>size</strong></td><td>为使用它的字段指定大小，例如 textarea 字段。选项：<code>tiny</code>、<code>small</code>、<code>large</code>、<code>huge</code>、<code>giant</code>。</td></tr><tr><td><strong>placeholder</strong></td><td>如果该字段支持占位符值。</td></tr><tr><td><strong>comment</strong></td><td>在字段下方放置描述性注释。</td></tr><tr><td><strong>commentAbove</strong></td><td>在字段上方放置注释。</td></tr><tr><td><strong>commentHtml</strong></td><td>允许在注释中使用 HTML 标记。选项：<code>true</code>、<code>false</code>。</td></tr><tr><td><strong>default</strong></td><td>指定字段的默认值。对于 <code>dropdown</code>、<code>checkboxlist</code>、<code>radio</code> 和 <code>balloon-selector</code> 小部件，您可以在此处指定一个选项键以使其默认被选中。</td></tr><tr><td><strong>defaultFrom</strong></td><td>从另一个模型属性的值中获取默认值。</td></tr><tr><td><strong>tab</strong></td><td>将字段分配到选项卡。</td></tr><tr><td><strong>cssClass</strong></td><td>为字段容器分配 CSS 类。</td></tr><tr><td><strong>autoFocus</strong></td><td>标记该字段在表单加载时获得焦点。默认值：<code>false</code>。</td></tr><tr><td><strong>readOnly</strong></td><td>防止字段被修改。选项：<code>true</code>、<code>false</code>。</td></tr><tr><td><strong>disabled</strong></td><td>防止字段被修改并将其从保存的数据中排除。选项：<code>true</code>、<code>false</code>。</td></tr><tr><td><strong>hidden</strong></td><td>从视图中隐藏字段并将其从保存的数据中排除。选项：<code>true</code>、<code>false</code>。</td></tr><tr><td><strong>stretch</strong></td><td>指定此字段是否拉伸以适应父级高度。</td></tr><tr><td><strong>context</strong></td><td>指定显示字段时应使用的上下文。上下文也可以通过在字段名称中使用 <code>@</code> 符号来传递，例如 <code>name@update</code>。</td></tr><tr><td><strong>dependsOn</strong></td><td>此字段<a href="./../extend/forms/field-dependencies.html">依赖</a>的其他字段名称数组，当其他字段被修改时，此字段将更新。</td></tr><tr><td><strong>changeHandler</strong></td><td>字段值更改时要调用的 AJAX 处理程序名称，可选。</td></tr><tr><td><strong>trigger</strong></td><td>使用触发器事件指定此字段的条件。</td></tr><tr><td><strong>preset</strong></td><td>允许字段值最初由另一个字段的值设置，通过输入预设转换器进行转换。</td></tr><tr><td><strong>required</strong></td><td>在字段标签旁边放置一个红色星号以表示该字段为必填项。请确保在模型上使用<a href="./../extend/database/traits.html">验证特征</a>，因为这不会由表单控制器强制执行。</td></tr><tr><td><strong>attributes</strong></td><td>指定要添加到表单字段元素的自定义 HTML 属性。</td></tr><tr><td><strong>containerAttributes</strong></td><td>指定要添加到表单字段容器的自定义 HTML 属性。</td></tr><tr><td><strong>order</strong></td><td>确定显示顺序时的数值权重，默认值每个字段递增 100 点。</td></tr><tr><td><strong>permissions</strong></td><td>当前后端用户必须拥有的<a href="./../extend/backend/permissions.html">权限</a>才能使用该字段。支持单个权限的字符串或权限数组（只需其中一个即可授予访问权限）。</td></tr></tbody></table></div><h3 id="选项卡属性"><a href="#选项卡属性" class="header-anchor">#</a> 选项卡属性</h3><p>在选项卡中指定字段定义的示例。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">tabs</span><span class="token punctuation">:</span>
    <span class="token key atrule">fields</span><span class="token punctuation">:</span>
        <span class="token key atrule">username</span><span class="token punctuation">:</span>
            <span class="token key atrule">type</span><span class="token punctuation">:</span> text
            <span class="token key atrule">label</span><span class="token punctuation">:</span> Username
            <span class="token key atrule">tab</span><span class="token punctuation">:</span> User

        <span class="token key atrule">groups</span><span class="token punctuation">:</span>
            <span class="token key atrule">type</span><span class="token punctuation">:</span> relation
            <span class="token key atrule">label</span><span class="token punctuation">:</span> Groups
            <span class="token key atrule">tab</span><span class="token punctuation">:</span> Groups
</code></pre></div><p>对于每个选项卡定义，即 <code>tabs</code> 和 <code>secondaryTabs</code>，您可以指定以下属性。</p><div class="table"><table tabindex="0"><thead><tr><th>属性</th><th>描述</th></tr></thead><tbody><tr><td><strong>stretch</strong></td><td>指定此选项卡是否拉伸以适应父级高度。</td></tr><tr><td><strong>defaultTab</strong></td><td>分配字段的默认选项卡。默认值：Misc。</td></tr><tr><td><strong>activeTab</strong></td><td>表单首次加载时选中的选项卡，名称或索引。默认值：<code>1</code></td></tr><tr><td><strong>icons</strong></td><td>使用选项卡名称作为键为选项卡分配图标。</td></tr><tr><td><strong>lazy</strong></td><td>点击时动态加载的选项卡数组。适用于包含大量内容的选项卡。</td></tr><tr><td><strong>identifiers</strong></td><td>用于定位选项卡的自定义 HTML 标识符数组。适用于使用 JavaScript 显示和隐藏选项卡。</td></tr><tr><td><strong>linkable</strong></td><td>确定选项卡是否可以使用 URL 片段进行链接。默认值：<code>true</code></td></tr><tr><td><strong>cssClass</strong></td><td>为选项卡容器分配 CSS 类。</td></tr><tr><td><strong>paneCssClass</strong></td><td>为单个选项卡面板分配 CSS 类。值是数组，键是选项卡索引或标签，值是 CSS 类。也可以指定为字符串，在这种情况下该值将应用于所有选项卡。</td></tr></tbody></table></div><p>应用属性到选项卡的示例。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">tabs</span><span class="token punctuation">:</span>
    <span class="token key atrule">stretch</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>
    <span class="token key atrule">defaultTab</span><span class="token punctuation">:</span> User
    <span class="token key atrule">cssClass</span><span class="token punctuation">:</span> text<span class="token punctuation">-</span>blue

    <span class="token key atrule">lazy</span><span class="token punctuation">:</span>
        <span class="token punctuation">-</span> Groups

    <span class="token key atrule">paneCssClass</span><span class="token punctuation">:</span>
        <span class="token key atrule">1</span><span class="token punctuation">:</span> first<span class="token punctuation">-</span>tab
        <span class="token key atrule">2</span><span class="token punctuation">:</span> second<span class="token punctuation">-</span>tab

    <span class="token key atrule">icons</span><span class="token punctuation">:</span>
        <span class="token key atrule">User</span><span class="token punctuation">:</span> icon<span class="token punctuation">-</span>user
        <span class="token key atrule">Groups</span><span class="token punctuation">:</span> icon<span class="token punctuation">-</span>group

    <span class="token key atrule">identifiers</span><span class="token punctuation">:</span>
        <span class="token key atrule">User</span><span class="token punctuation">:</span> userTab

    <span class="token key atrule">fields</span><span class="token punctuation">:</span>
        <span class="token comment"># [...]</span>
</code></pre></div><h3 id="自定义字段类型"><a href="#自定义字段类型" class="header-anchor">#</a> 自定义字段类型</h3><p>有各种原生字段类型可用于 <strong>type</strong> 设置。也可以通过指定<a href="./../extend/forms/form-widgets.html">表单字段小部件</a>的 PHP 类名直接渲染字段。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">blog_content</span><span class="token punctuation">:</span>
    <span class="token key atrule">type</span><span class="token punctuation">:</span> Backend\\FormWidgets\\RichEditor
    <span class="token key atrule">size</span><span class="token punctuation">:</span> huge
</code></pre></div><h3 id="嵌套字段选择"><a href="#嵌套字段选择" class="header-anchor">#</a> 嵌套字段选择</h3><div class="language-yaml extra-class"><pre class="language-yaml"><code>avatar<span class="token punctuation">[</span>name<span class="token punctuation">]</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Avatar
    <span class="token key atrule">comment</span><span class="token punctuation">:</span> will be saved in the Avatar table
</code></pre></div><p>上面的示例将在 PHP 中分别通过 <code>$record-&gt;avatar-&gt;name</code> 或 <code>$record-&gt;avatar[&#39;name&#39;]</code> 获取和保存值。</p><h3 id="字段门面"><a href="#字段门面" class="header-anchor">#</a> 字段门面</h3><p>有时您可能需要显示一个字段但阻止其被提交。可以通过在字段名称前添加下划线 (_) 将字段定义为门面。这些字段会被自动清除，不再保存到模型中，例如以下的 <code>_map</code> 字段。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">address</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Title
    <span class="token key atrule">type</span><span class="token punctuation">:</span> text

<span class="token key atrule">_map</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Point your address on the map
    <span class="token key atrule">type</span><span class="token punctuation">:</span> mapviewer
</code></pre></div><h2 id="字段条件"><a href="#字段条件" class="header-anchor">#</a> 字段条件</h2><p>有时您可能需要在某些条件下操作表单字段的值或外观，例如，您可能希望在勾选复选框时隐藏输入框或预设另一个字段的值。</p><h3 id="触发器事件"><a href="#触发器事件" class="header-anchor">#</a> 触发器事件</h3><p>触发器事件使用 <code>trigger</code> 表单字段属性定义，是一种简单的基于浏览器的解决方案，使用 JavaScript。它允许您根据另一个元素的状态更改元素属性，例如可见性或值。以下是示例定义：</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">is_delayed</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Send later
    <span class="token key atrule">comment</span><span class="token punctuation">:</span> Place a tick in this box if you want to send this message at a later time.
    <span class="token key atrule">type</span><span class="token punctuation">:</span> checkbox

<span class="token key atrule">send_at</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Send date
    <span class="token key atrule">type</span><span class="token punctuation">:</span> datepicker
    <span class="token key atrule">cssClass</span><span class="token punctuation">:</span> field<span class="token punctuation">-</span>indent
    <span class="token key atrule">trigger</span><span class="token punctuation">:</span>
        <span class="token key atrule">action</span><span class="token punctuation">:</span> show
        <span class="token key atrule">field</span><span class="token punctuation">:</span> is_delayed
        <span class="token key atrule">condition</span><span class="token punctuation">:</span> checked
</code></pre></div><p>在上面的示例中，<code>send_at</code> 表单字段仅在 <code>is_delayed</code> 字段被勾选时才会显示。换句话说，当另一个表单输入（field）被勾选（condition）时，该字段将显示（action）。</p><p><code>trigger</code> 定义指定以下属性。</p><div class="table"><table tabindex="0"><thead><tr><th>属性</th><th>描述</th></tr></thead><tbody><tr><td><strong>action</strong></td><td>定义满足条件时应用于此字段的操作。支持的值：<code>show</code>、<code>hide</code>、<code>enable</code>、<code>disable</code>、<code>empty</code>、<code>fill[somevalue]</code>。</td></tr><tr><td><strong>field</strong></td><td>触发操作的另一个字段名称的引用。示例：<code>color</code> 或 <code>color[]</code>。</td></tr><tr><td><strong>condition</strong></td><td>确定指定字段应满足的条件，以使条件被视为 <code>true</code>。支持的值：<code>checked</code>、<code>unchecked</code>、<code>value[somevalue]</code>。</td></tr></tbody></table></div><h4 id="多个操作"><a href="#多个操作" class="header-anchor">#</a> 多个操作</h4><p>您可以通过使用管道 <code>|</code> 符号分隔来组合多个操作。以下将在触发条件满足时同时显示和清空输入。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">trigger</span><span class="token punctuation">:</span>
    <span class="token key atrule">action</span><span class="token punctuation">:</span> show<span class="token punctuation">|</span>empty
    <span class="token key atrule">condition</span><span class="token punctuation">:</span> checked
    <span class="token key atrule">field</span><span class="token punctuation">:</span> name
</code></pre></div><h4 id="多值条件"><a href="#多值条件" class="header-anchor">#</a> 多值条件</h4><p>使用 <code>value[]</code> 条件时，您可以通过在第一个值后传递额外的值来查找多个值，格式为 <code>value[][]</code>。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">trigger</span><span class="token punctuation">:</span>
    <span class="token key atrule">action</span><span class="token punctuation">:</span> show
    <span class="token key atrule">condition</span><span class="token punctuation">:</span> value<span class="token punctuation">[</span>csv<span class="token punctuation">]</span><span class="token punctuation">[</span>csv_custom<span class="token punctuation">]</span>
    <span class="token key atrule">field</span><span class="token punctuation">:</span> file_format
</code></pre></div><h4 id="通配符值条件"><a href="#通配符值条件" class="header-anchor">#</a> 通配符值条件</h4><p>您可以使用通配符字符（<code>*</code>）检查 <code>value[]</code> 条件是否匹配多个可能的值，例如，<strong>foo*</strong> 匹配以 &quot;foo&quot; 开头的任何内容，<strong>*bar</strong> 匹配以 &quot;bar&quot; 结尾的任何内容。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">trigger</span><span class="token punctuation">:</span>
    <span class="token key atrule">action</span><span class="token punctuation">:</span> show
    <span class="token key atrule">condition</span><span class="token punctuation">:</span> value<span class="token punctuation">[</span><span class="token important">*.mp4</span><span class="token punctuation">]</span>
    <span class="token key atrule">field</span><span class="token punctuation">:</span> file_name
</code></pre></div><h4 id="多字段值"><a href="#多字段值" class="header-anchor">#</a> 多字段值</h4><p>某些字段，例如 <a href="./form/field-checkboxlist.html">Checkbox List</a> 和 <a href="./form/widget-taglist.html">Tag List</a>，会将其值存储为数组。引用这些字段时，字段名称应使用数组后缀（<code>[]</code>）来查看所有可能的值。例如，如果 <code>colors</code> 字段名称支持多个值，则应使用字段名称 <code>colors[]</code> 作为引用。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">trigger</span><span class="token punctuation">:</span>
    <span class="token key atrule">action</span><span class="token punctuation">:</span> show
    <span class="token key atrule">condition</span><span class="token punctuation">:</span> value<span class="token punctuation">[</span>red<span class="token punctuation">]</span><span class="token punctuation">[</span>green<span class="token punctuation">]</span>
    <span class="token key atrule">field</span><span class="token punctuation">:</span> colors<span class="token punctuation">[</span><span class="token punctuation">]</span>
</code></pre></div><h4 id="引用父级字段"><a href="#引用父级字段" class="header-anchor">#</a> 引用父级字段</h4><p>通常字段名称引用同一级别表单中的字段。例如，如果此字段在<a href="./form/widget-repeater.html">重复器小部件</a>中，则只会检查同一重复器小部件中的字段。但是，如果字段名称前面有脱字符 <code>^</code>，如：<code>^parent_field</code>，它将引用比字段本身高一级的重复器小部件或表单。</p><p>在下面的示例中，当 <code>type</code> 字段设置为 <strong>Complex</strong> 时，<code>colors</code> 字段将显示。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">fields</span><span class="token punctuation">:</span>
    <span class="token key atrule">type</span><span class="token punctuation">:</span>
        <span class="token key atrule">label</span><span class="token punctuation">:</span> Type
        <span class="token key atrule">type</span><span class="token punctuation">:</span> dropdown
        <span class="token key atrule">options</span><span class="token punctuation">:</span>
            <span class="token key atrule">1</span><span class="token punctuation">:</span> Simple
            <span class="token key atrule">2</span><span class="token punctuation">:</span> Complex

    <span class="token key atrule">content</span><span class="token punctuation">:</span>
        <span class="token key atrule">label</span><span class="token punctuation">:</span> Content
        <span class="token key atrule">type</span><span class="token punctuation">:</span> nestedform
        <span class="token key atrule">form</span><span class="token punctuation">:</span>
            <span class="token key atrule">fields</span><span class="token punctuation">:</span>
                <span class="token key atrule">colors</span><span class="token punctuation">:</span>
                    <span class="token key atrule">label</span><span class="token punctuation">:</span> Colors
                    <span class="token key atrule">type</span><span class="token punctuation">:</span> colorpicker
                    <span class="token key atrule">trigger</span><span class="token punctuation">:</span>
                        <span class="token key atrule">action</span><span class="token punctuation">:</span> show
                        <span class="token key atrule">field</span><span class="token punctuation">:</span> ^type
                        <span class="token key atrule">condition</span><span class="token punctuation">:</span> value<span class="token punctuation">[</span><span class="token number">2</span><span class="token punctuation">]</span>
</code></pre></div><div class="custom-block tip"><p>此外，如果使用多个脱字符 <code>^</code>，它将引用更高的层级：<code>^^grand_parent_field</code>、<code>^^^grand_grand_parent_field</code>，依此类推。</p></div><h3 id="输入预设转换器"><a href="#输入预设转换器" class="header-anchor">#</a> 输入预设转换器</h3><p>输入预设转换器使用 <code>preset</code> 表单字段属性定义，允许您将输入到一个元素中的文本转换为另一个输入元素中的 URL、slug 或文件名值。</p><p>在此示例中，当用户在 <code>title</code> 字段中输入文本时，我们将自动填充 <code>url</code> 字段的值。如果在 Title 中输入 <strong>Hello world</strong>，URL 将随之变为转换后的值 <strong>/hello-world</strong>。此行为仅在目标字段（<code>url</code>）为空且未被触碰时才会发生。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">title</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Title

<span class="token key atrule">url</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> URL
    <span class="token key atrule">preset</span><span class="token punctuation">:</span>
        <span class="token key atrule">field</span><span class="token punctuation">:</span> title
        <span class="token key atrule">type</span><span class="token punctuation">:</span> url
</code></pre></div><p>或者，<code>preset</code> 值也可以是仅引用 <strong>field</strong> 的字符串，<code>type</code> 选项将默认为 <strong>slug</strong>。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">slug</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Slug
    <span class="token key atrule">preset</span><span class="token punctuation">:</span> title
</code></pre></div><p>以下是 <code>preset</code> 选项可用的选项：</p><div class="table"><table tabindex="0"><thead><tr><th>选项</th><th>描述</th></tr></thead><tbody><tr><td><strong>field</strong></td><td>定义要从中获取值的其他字段名称。</td></tr><tr><td><strong>type</strong></td><td>指定转换类型。请参阅下面的支持值。</td></tr><tr><td><strong>prefixInput</strong></td><td>可选，使用 CSS 选择器在提供的输入元素中找到的值作为转换值的前缀。</td></tr></tbody></table></div><p>以下是支持的类型：</p><div class="table"><table tabindex="0"><thead><tr><th>类型</th><th>描述</th></tr></thead><tbody><tr><td><strong>exact</strong></td><td>复制精确的值</td></tr><tr><td><strong>slug</strong></td><td>将复制的值格式化为 slug</td></tr><tr><td><strong>url</strong></td><td>与 slug 相同，但带有 / 前缀</td></tr><tr><td><strong>camel</strong></td><td>将复制的值格式化为 camelCase</td></tr><tr><td><strong>file</strong></td><td>将复制的值格式化为文件名，空格替换为破折号</td></tr></tbody></table></div>`,54))])}const b=p(d,[["render",i]]);export{y as __pageData,b as default};
